import sys
from collections import deque

def bfs(grid, start, visited):
    queue = deque([start])
    visited.add(start)
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '#' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

def is_connected(grid):
    visited = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '#' and (i, j) not in visited:
                bfs(grid, (i, j), visited)
                return len(visited) == sum(row.count('#') for row in grid)
    return False

def min_deletions_to_disconnect(grid):
    if not is_connected(grid):
        return 0
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == '#':
                grid[i][j] = '.'
                if not is_connected(grid):
                    return 1
                grid[i][j] = '#'
    for i in range(len(grid)):
        for j in range(len(grid)):
            if grid[i][j] == '#':
                grid[i][j], grid[i+1][j] = grid[i+1][j], grid[i][j]
                if not is_connected(grid):
                    return 2
                grid[i][j], grid[i+1][j] = grid[j+1][i], grid[i][j]
                grid[i][j], grid[i][j+1] = grid[i][j+1], grid[i][j]
                if not is_connected(grid):
                    return min_deletions_to_disconnect(grid)
                grid[i][j], grid[i][j+1] = grid[j][i+1], grid[i][j]
    return -1

input = sys.stdin.read().splitlines()
n, m = map(int, input[0].split())
grid = [list(line) for line in input[1:]]
print(min_deletions_to_disconnect(grid))
